package com.cxy.workbench;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/** Read-only calendar over the same canonical calendarEvents; deadlines are not added. */
final class CalendarPage {
 static YearMonth month=YearMonth.now(ZoneId.of("Asia/Shanghai"));static String selected="";
 static String version(){return month.toString()+selected;}
 static ArrayList<JSONObject> events(JSONObject snapshot){ArrayList<JSONObject> out=new ArrayList<>();JSONArray a=snapshot==null?null:snapshot.optJSONArray("calendarEvents");if(a!=null)for(int n=0;n<a.length();n++){JSONObject e=a.optJSONObject(n);if(e!=null)out.add(e);}Collections.sort(out,(x,y)->x.optString("date").compareTo(y.optString("date")));return out;}
 static void refresh(MainActivity a){a.lastRender="";a.render();HyperStyle.enter(a.content);}
 static void render(MainActivity a,LinearLayout parent){
  ArrayList<JSONObject> all=events(Store.read(a,"actions"));LinearLayout card=DeviceCards.panel(a,parent);card.setPadding(a.dp(14),a.dp(10),a.dp(14),a.dp(10));
  LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);card.addView(bar);a.iconButton(bar,"back","上个月",()->{month=month.minusMonths(1);selected="";refresh(a);});TextView title=a.text(month.getYear()+"年"+month.getMonthValue()+"月",20,HyperStyle.ink(a));title.setGravity(Gravity.CENTER);title.setTypeface(Typeface.create("sans-serif-medium",0));bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));a.iconButton(bar,"chevron","下个月",()->{month=month.plusMonths(1);selected="";refresh(a);});
  LinearLayout week=new LinearLayout(a);card.addView(week);for(String name:new String[]{"一","二","三","四","五","六","日"}){TextView t=a.text(name,13,HyperStyle.muted(a));t.setGravity(Gravity.CENTER);t.setPadding(0,a.dp(8),0,a.dp(6));week.addView(t,new LinearLayout.LayoutParams(0,-2,1));}
  HashSet<String> dates=new HashSet<>();for(JSONObject e:all)dates.add(e.optString("date"));LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));LocalDate first=month.atDay(1);int lead=first.getDayOfWeek().getValue()-1;int weeks=(lead+month.lengthOfMonth()+6)/7;
  for(int row=0;row<weeks;row++){if(!selected.isEmpty()){LocalDate chosenDay=LocalDate.parse(selected);int chosenRow=(lead+chosenDay.getDayOfMonth()-1)/7;if(row!=chosenRow)continue;}LinearLayout line=new LinearLayout(a);card.addView(line);for(int col=0;col<7;col++){LocalDate day=first.plusDays(row*7+col-lead);String date=day.toString();boolean active=day.getMonthValue()==month.getMonthValue(),chosen=date.equals(selected),isToday=day.equals(today);LinearLayout cell=a.column();cell.setGravity(Gravity.CENTER);cell.setPadding(0,a.dp(2),0,a.dp(2));cell.setBackground(HyperStyle.press(a,chosen?HyperStyle.accent(a):isToday?HyperStyle.wash(a):android.graphics.Color.TRANSPARENT,14));TextView num=a.text(String.valueOf(day.getDayOfMonth()),16,chosen?(HyperStyle.dark(a)?0xff10233f:android.graphics.Color.WHITE):active?HyperStyle.ink(a):HyperStyle.muted(a));num.setGravity(Gravity.CENTER);num.setPadding(0,0,0,0);cell.addView(num);TextView dot=a.text(dates.contains(date)?"●":" ",8,chosen?android.graphics.Color.WHITE:HyperStyle.accent(a));dot.setGravity(Gravity.CENTER);dot.setPadding(0,0,0,0);cell.addView(dot);cell.setContentDescription(date+(dates.contains(date)?"，有日程":""));HyperStyle.pressMotion(cell);cell.setOnClickListener(v->{month=YearMonth.from(day);selected=date;refresh(a);});line.addView(cell,new LinearLayout.LayoutParams(0,a.dp(44),1));}}
  LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.setPadding(a.dp(8),a.dp(18),a.dp(8),0);parent.addView(heading);TextView label=a.text(selected.isEmpty()?"本月日程":selected,18,HyperStyle.ink(a));label.setTypeface(Typeface.create("sans-serif-medium",0));heading.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView reset=a.text(selected.isEmpty()?"回到本月":"查看整月",14,HyperStyle.accent(a));reset.setPadding(a.dp(8),a.dp(12),0,a.dp(12));reset.setOnClickListener(v->{if(selected.isEmpty())month=YearMonth.now(ZoneId.of("Asia/Shanghai"));selected="";refresh(a);});heading.addView(reset);
  int shown=0;String previous="";for(JSONObject e:all){String date=e.optString("date");if(selected.isEmpty()?!date.startsWith(month.toString()):!selected.equals(date))continue;shown++;if(selected.isEmpty()&&!date.equals(previous)){TextView day=a.text(date,14,HyperStyle.accent(a));day.setPadding(a.dp(8),a.dp(12),0,0);parent.addView(day);previous=date;}
   LinearLayout event=DeviceCards.panel(a,parent);String state=e.optString("status","");boolean uncertain=state.contains("冲突")||state.contains("待确认")||e.optString("time").contains("待确认");TextView time=a.text(e.optString("time","时间未定"),16,uncertain?0xffb37a28:HyperStyle.accent(a));event.addView(time);TextView name=a.text(e.optString("title"),18,HyperStyle.ink(a));name.setTypeface(Typeface.create("sans-serif-medium",0));event.addView(name);String place=e.optString("place","");if(!place.isEmpty()&&!place.equals("未提及")&&!place.equals("未在此消息重申"))event.addView(a.text(place,15,HyperStyle.muted(a)));if(!state.isEmpty())event.addView(a.text(state,14,uncertain?0xffb37a28:HyperStyle.muted(a)));
   String note=e.optString("note","");if(!note.isEmpty()){TextView detail=a.text(note,15,HyperStyle.muted(a));detail.setLineSpacing(a.dp(3),1);detail.setVisibility(View.GONE);TextView toggle=a.text("详情  ⌄",14,HyperStyle.accent(a));toggle.setPadding(0,a.dp(12),0,a.dp(4));toggle.setOnClickListener(v->{HyperStyle.expand(event);boolean open=detail.getVisibility()==View.GONE;detail.setVisibility(open?View.VISIBLE:View.GONE);toggle.setText(open?"收起  ⌃":"详情  ⌄");});event.addView(toggle);event.addView(detail);}
  }
  if(shown==0)a.empty(parent,"calendar",selected.isEmpty()?"本月没有已记录日程":"这一天没有已记录日程","",null);
 }
}
